#' RD Local Randomization
#'
#' 
#' @param data .
#' @param outcome .
#' @param running .
#' @param covs .
#' @param cutVar .
#' @param cutoff .
#' @param windowMode .
#' @param wLeft .
#' @param wRight .
#' @param statistic .
#' @param polyOrder .
#' @param reps .
#' @param nwindows .
#' @param winTable .
#' @param seed .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$sample} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$test} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$winSel} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$sample$asDF}
#'
#' \code{as.data.frame(results$sample)}
#'
#' @export
rdlr <- function(
    data,
    outcome,
    running,
    covs,
    cutVar,
    cutoff = 0,
    windowMode = "manual",
    wLeft = 1,
    wRight = 1,
    statistic = "diffmeans",
    polyOrder = 0,
    reps = 1000,
    nwindows = 10,
    winTable = FALSE,
    seed = 1,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("rdlr requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(running)) running <- jmvcore::resolveQuo(jmvcore::enquo(running))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(cutVar)) cutVar <- jmvcore::resolveQuo(jmvcore::enquo(cutVar))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(running), running, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(cutVar), cutVar, NULL))


    options <- rdlrOptions$new(
        outcome = outcome,
        running = running,
        covs = covs,
        cutVar = cutVar,
        cutoff = cutoff,
        windowMode = windowMode,
        wLeft = wLeft,
        wRight = wRight,
        statistic = statistic,
        polyOrder = polyOrder,
        reps = reps,
        nwindows = nwindows,
        winTable = winTable,
        seed = seed,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- rdlrClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

